namespace BARANG.Core.Infrastructure.Workflow;

public sealed class WorkflowDefinitionRuntime(CoreDbContext db, ITransactionExecutor tx, ICompanyContext company, ICurrentActor actor, IArtworkFileAdministration files, TimeProvider clock) : IWorkflowDefinitionRuntime
{
    private Guid Company => company.CompanyId is { } id && id != Guid.Empty ? id : throw new InvalidOperationException("Company context is required.");
    private Guid Actor => Guid.TryParse(actor.Actor.UserId, out Guid id) ? id : throw new InvalidOperationException("Actor context is required.");
    private DateTimeOffset Now => clock.GetUtcNow();
    private static readonly object[] Empty = [];
    private static readonly string[] Outcomes = ["Approve", "Reject"];

    public Task<Result<object>> StartAsync(StartDefinitionWorkflowCommand command, CancellationToken ct) => tx.ExecuteAsync(t => StartInsideTransactionAsync(command.OrderId, t), ct);
    public async Task<Result<object>> StartInsideTransactionAsync(Guid orderId, CancellationToken ct)
    {
        await using DbConnection c = db.Database.GetDbConnection(); if (c.State != ConnectionState.Open) await c.OpenAsync(ct); await SetCompany(c, ct); DbTransaction? transaction = db.Database.CurrentTransaction?.GetDbTransaction();
        await using DbCommand existing = CmdTx(c, "select id from barang.workflow_instances where company_id=@company and order_id=@order", ("company", Company), ("order", orderId), transaction); object? found = await existing.ExecuteScalarAsync(ct); if (found is Guid old) return Result.Success<object>(new { id = old, orderId, idempotent = true });
        Guid definition; Guid version; await using (DbCommand q = CmdTx(c, "select d.id,d.active_version_id from barang.workflow_definitions d where d.company_id=@company and d.code='BARANG.ORDER'", ("company", Company), transaction)) await using (DbDataReader r = await q.ExecuteReaderAsync(ct)) { if (!await r.ReadAsync(ct) || r.IsDBNull(1)) return Result.Failure<object>(Error.BusinessRule("workflow.definition.no_published_version")); definition = r.GetGuid(0); version = r.GetGuid(1); }
        Guid instance = Guid.NewGuid(); await using (DbCommand ins = CmdTx(c, "insert into barang.workflow_instances(id,company_id,order_id,definition_code,provider_instance_id,current_stage,status,started_at_utc,updated_at_utc,version,\"DefinitionVersionId\") values(@id,@company,@order,'BARANG.ORDER',@provider,'Started','Running',@now,@now,1,@version)", ("id", instance), ("company", Company), ("order", orderId), ("provider", instance.ToString()), ("now", Now), ("version", version), transaction)) await ins.ExecuteNonQueryAsync(ct);
        await using DbCommand start = CmdTx(c, "select id,node_key,position_id from barang.workflow_definition_nodes where company_id=@company and definition_version_id=@version and type='Start'", ("company", Company), ("version", version), transaction); await using DbDataReader sr = await start.ExecuteReaderAsync(ct); if (!await sr.ReadAsync(ct)) return Result.Failure<object>(Error.BusinessRule("workflow.definition.start_missing")); Guid startNode = sr.GetGuid(0); await sr.DisposeAsync();
        await CreateNextTasks(c, transaction, instance, version, startNode, ct); await History(c, transaction, instance, null, "InstanceStarted", null, ct); return Result.Success<object>(new { id = instance, orderId, definitionVersionId = version });
    }

    public Task<Result<object>> ClaimTaskAsync(Guid id, long version, CancellationToken ct) => tx.ExecuteAsync(async t => { await using DbConnection c = db.Database.GetDbConnection(); if (c.State != ConnectionState.Open) await c.OpenAsync(t); await SetCompany(c, t); DbTransaction? tr = db.Database.CurrentTransaction?.GetDbTransaction(); await using DbCommand q = CmdTx(c, "update barang.workflow_runtime_tasks set status='Claimed',claimed_at_utc=@now,claimed_by_user_id=@actor,version=version+1 where company_id=@company and id=@id and version=@version and status in ('Open','Claimed') and (claimed_by_user_id is null or claimed_by_user_id=@actor) returning version", ("now", Now), ("actor", Actor), ("company", Company), ("id", id), ("version", version), tr); object? value = await q.ExecuteScalarAsync(t); return value is null ? Result.Failure<object>(Error.Concurrency("workflow.task.concurrency")) : Result.Success<object>(new { id, claimedByUserId = Actor, version = Convert.ToInt64(value, System.Globalization.CultureInfo.InvariantCulture) }); }, ct);
    public Task<Result<object>> ReleaseTaskAsync(Guid id, long version, CancellationToken ct) => tx.ExecuteAsync(async t => { await using DbConnection c = db.Database.GetDbConnection(); if (c.State != ConnectionState.Open) await c.OpenAsync(t); await SetCompany(c, t); DbTransaction? tr = db.Database.CurrentTransaction?.GetDbTransaction(); await using DbCommand q = CmdTx(c, "update barang.workflow_runtime_tasks set status='Open',claimed_at_utc=null,claimed_by_user_id=null,claimed_on_behalf_of_user_id=null,version=version+1 where company_id=@company and id=@id and version=@version and claimed_by_user_id=@actor returning version", ("company", Company), ("id", id), ("version", version), ("actor", Actor), tr); object? value = await q.ExecuteScalarAsync(t); return value is null ? Result.Failure<object>(Error.BusinessRule("workflow.task.not_owner")) : Result.Success<object>(new { id, status = "Open", version = Convert.ToInt64(value, System.Globalization.CultureInfo.InvariantCulture) }); }, ct);
    public Task<Result<object>> CompleteTaskAsync(Guid id, string? resultJson, IReadOnlyList<DecisionAttachmentCommand>? attachments, long version, CancellationToken ct) => tx.ExecuteAsync(t => CompleteInside(id, resultJson, attachments, version, t), ct);
    private async Task<Result<object>> CompleteInside(Guid id, string? resultJson, IReadOnlyList<DecisionAttachmentCommand>? attachments, long version, CancellationToken ct)
    {
        await using DbConnection c = db.Database.GetDbConnection(); if (c.State != ConnectionState.Open) await c.OpenAsync(ct); await SetCompany(c, ct); DbTransaction? tr = db.Database.CurrentTransaction?.GetDbTransaction(); Guid instance; Guid node; string status; Guid? owner; string nodeKey; await using (DbCommand q = CmdTx(c, "select workflow_instance_id,definition_node_id,node_key,status,claimed_by_user_id from barang.workflow_runtime_tasks where company_id=@company and id=@id for update", ("company", Company), ("id", id), tr)) await using (DbDataReader r = await q.ExecuteReaderAsync(ct)) { if (!await r.ReadAsync(ct)) return Result.Failure<object>(Error.NotFound("workflow.task.not_found")); instance = r.GetGuid(0); node = r.GetGuid(1); nodeKey = r.GetString(2); status = r.GetString(3); owner = r.IsDBNull(4) ? null : r.GetGuid(4); }
        if (status == "Completed") return Result.Success<object>(new { id, status }); if (owner != Actor) return Result.Failure<object>(Error.BusinessRule("workflow.task.not_owner"));
        JsonDocument? result = null; try { if (!string.IsNullOrWhiteSpace(resultJson)) result = JsonDocument.Parse(resultJson); } catch (JsonException) { return Result.Failure<object>(Error.Validation("workflow.task.invalid_result")); }
        await using (DbCommand u = CmdTx(c, "update barang.workflow_runtime_tasks set status='Completed',completed_at_utc=@now,completed_by_user_id=@actor,result_json=@result::jsonb,version=version+1 where company_id=@company and id=@id and version=@version", ("now", Now), ("actor", Actor), ("result", resultJson ?? "{}"), ("company", Company), ("id", id), ("version", version), tr)) if (await u.ExecuteNonQueryAsync(ct) != 1) return Result.Failure<object>(Error.Concurrency("workflow.task.concurrency"));
        string? outcome = result?.RootElement.TryGetProperty("outcome", out var outcomeValue) == true && outcomeValue.ValueKind == JsonValueKind.String ? outcomeValue.GetString() : null; Guid historyId = await History(c, tr, instance, id, "TaskCompleted", resultJson, ct); await SaveAttachments(c, tr, historyId, instance, id, resultJson, attachments, ct); await CreateNextTasks(c, tr, instance, await VersionForInstance(c, tr, instance, ct), node, ct, outcome); return Result.Success<object>(new { id, status = "Completed" });
    }

    public async Task<Result<object>> EligibleTasksAsync(CartableTaskQuery query, CancellationToken ct) => await TaskPage(query, false, ct);
    public async Task<Result<object>> MyReferralsAsync(CartableTaskQuery query, CancellationToken ct) => await TaskPage(query, true, ct);
    private async Task<Result<object>> TaskPage(CartableTaskQuery query, bool referrals, CancellationToken ct) { CartableTaskQuery q = query;
    await using DbConnection c = db.Database.GetDbConnection(); await c.OpenAsync(ct); await SetCompany(c, ct); string condition = referrals ? "t.completed_by_user_id=@actor" : "t.status in ('Open','Claimed')"; string search = string.IsNullOrWhiteSpace(q.Search) ? "" : q.Search.Trim(); List<object> rows = []; await using DbCommand cmd = Cmd(c, $"select t.id,t.workflow_instance_id,i.order_id,t.node_key,t.status,t.created_at_utc,t.claimed_by_user_id,t.version,o.order_number,o.order_date,o.status from barang.workflow_runtime_tasks t join barang.workflow_instances i on i.id=t.workflow_instance_id and i.company_id=t.company_id join barang.orders o on o.id=i.order_id and o.company_id=i.company_id where t.company_id=@company and {condition} and (@search='' or coalesce(o.order_number,'') ilike '%'||@search||'%') order by t.created_at_utc desc,t.id offset @skip limit @take", ("company", Company), ("actor", Actor), ("search", search), ("skip", Math.Max(0, q.Page - 1) * Math.Clamp(q.PageSize, 1, 100)), ("take", Math.Clamp(q.PageSize, 1, 100))); await using DbDataReader r = await cmd.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) rows.Add(new { id = r.GetGuid(0), workflowInstanceId = r.GetGuid(1), orderId = r.GetGuid(2), nodeKey = r.GetString(3), stageKey = r.GetString(3), status = r.GetString(4), createdAtUtc = r.GetFieldValue<DateTimeOffset>(5), claimedByUserId = r.IsDBNull(6) ? (Guid?)null : r.GetGuid(6), version = r.GetInt64(7), orderNumber = r.IsDBNull(8) ? null : r.GetString(8), orderDate = r.GetFieldValue<DateOnly>(9), effectiveStatusCode = r.GetString(10), outcomes = Outcomes, isStarred = false, seen = false, followUpAtUtc = (DateTimeOffset?)null }); return Result.Success<object>(new { items = rows, page = q.Page, pageSize = q.PageSize, total = rows.Count }); }

    public async Task<Result<CartableWorkflowContextView>> WorkflowContextAsync(Guid id, CancellationToken ct) { await using DbConnection c = db.Database.GetDbConnection(); await c.OpenAsync(ct); await SetCompany(c, ct); await using DbCommand q = Cmd(c, "select node_key from barang.workflow_runtime_tasks where company_id=@company and id=@id", ("company", Company), ("id", id)); object? key = await q.ExecuteScalarAsync(ct); if (key is null) return Result.Failure<CartableWorkflowContextView>(Error.NotFound("workflow.task.not_found")); return Result.Success(new CartableWorkflowContextView(null, null, new("", key.ToString() ?? "", ""), null, true, [new("Approve", null, true), new("Reject", null, false)])); }
    public Task<Result<CartableWorkloadSummary>> WorkloadSummaryAsync(CancellationToken ct) => Task.FromResult(Result.Success(new CartableWorkloadSummary(0, 0, 0, 0)));
    public async Task<Result<IReadOnlyList<object>>> TasksAsync(Guid instanceId, CancellationToken ct)
    { await using DbConnection c = db.Database.GetDbConnection(); await c.OpenAsync(ct); await SetCompany(c, ct); List<object> rows = []; await using DbCommand q = Cmd(c, "select id,node_key,status,created_at_utc,completed_at_utc,version from barang.workflow_runtime_tasks where company_id=@company and workflow_instance_id=@instance order by created_at_utc,id", ("company", Company), ("instance", instanceId)); await using DbDataReader r = await q.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) rows.Add(new { id = r.GetGuid(0), nodeKey = r.GetString(1), status = r.GetString(2), createdAtUtc = r.GetFieldValue<DateTimeOffset>(3), completedAtUtc = r.IsDBNull(4) ? (DateTimeOffset?)null : r.GetFieldValue<DateTimeOffset>(4), version = r.GetInt64(5) }); return Result.Success<IReadOnlyList<object>>(rows); }
    public Task<Result<object>> QuickPreviewAsync(Guid id, CancellationToken ct) => Task.FromResult(Result.Success<object>(new { id }));
    public async Task<Result<object>> SetPersonalStateAsync(Guid taskId, CartablePersonalStateCommand command, CancellationToken ct)
    {
        await using DbConnection c = db.Database.GetDbConnection(); await c.OpenAsync(ct); await SetCompany(c, ct);
        await using DbCommand q = Cmd(c, "insert into barang.cartable_personal_states(id,company_id,user_id,runtime_task_id,is_starred,seen_at_utc,version,follow_up_at_utc) values(@id,@company,@user,@task,coalesce(@starred,false),case when @seen then @now else null end,1,@follow) on conflict (company_id,user_id,runtime_task_id) do update set is_starred=coalesce(@starred,cartable_personal_states.is_starred),seen_at_utc=case when @seen then @now else cartable_personal_states.seen_at_utc end,follow_up_at_utc=@follow,version=cartable_personal_states.version+1", ("id", Guid.NewGuid()), ("company", Company), ("user", Actor), ("task", taskId), ("starred", command.IsStarred), ("seen", command.Seen ?? false), ("now", Now), ("follow", command.FollowUpAtUtc));
        await q.ExecuteNonQueryAsync(ct); return Result.Success<object>(new { taskId, isStarred = command.IsStarred, seen = command.Seen, followUpAtUtc = command.FollowUpAtUtc });
    }
    public Task<Result<object>> WorkbenchAsync(CartableWorkbenchQuery query, CancellationToken ct) => TaskPage(query.Query, query.Historical, ct);
    public async Task<Result<CartableWorkbenchDetailView>> WorkbenchDetailAsync(Guid id, bool historical, CancellationToken ct)
    { await using DbConnection c = db.Database.GetDbConnection(); await c.OpenAsync(ct); await SetCompany(c, ct); await using DbCommand q = Cmd(c, "select o.id,o.order_number,o.order_date,o.status,o.priority,c.display_name,count(i.id),coalesce(sum(i.quantity),0) from barang.workflow_runtime_tasks t join barang.workflow_instances wi on wi.id=t.workflow_instance_id and wi.company_id=t.company_id join barang.orders o on o.id=wi.order_id and o.company_id=wi.company_id left join barang.customers c on c.id=o.customer_id and c.company_id=o.company_id left join barang.order_items i on i.order_id=o.id and i.company_id=o.company_id and i.is_active where t.company_id=@company and t.id=@id group by o.id,o.order_number,o.order_date,o.status,o.priority,c.display_name", ("company", Company), ("id", id)); await using DbDataReader r = await q.ExecuteReaderAsync(ct); if (!await r.ReadAsync(ct)) return Result.Failure<CartableWorkbenchDetailView>(Error.NotFound("workflow.task.not_found")); Guid orderId = r.GetGuid(0); CartableWorkbenchSummary summary = new(r.IsDBNull(1) ? null : r.GetString(1), r.IsDBNull(5) ? null : r.GetString(5), r.GetFieldValue<DateOnly>(2), r.GetString(3), [], r.IsDBNull(4) ? "Normal" : r.GetString(4), r.GetInt32(6), r.GetDecimal(7), null, null, null); return Result.Success(new CartableWorkbenchDetailView(orderId, summary, null)); }
    public Task<Result<IReadOnlyList<object>>> WorkbenchHistoryAsync(Guid id, CancellationToken ct) => Task.FromResult(Result.Success<IReadOnlyList<object>>(Array.Empty<object>()));
    public async Task<Result<IReadOnlyList<object>>> DecisionAttachmentsAsync(Guid orderId, CancellationToken ct)
    { await using DbConnection c = db.Database.GetDbConnection(); await c.OpenAsync(ct); await SetCompany(c, ct); List<object> rows = []; await using DbCommand q = Cmd(c, "select a.id,a.runtime_task_id,a.file_id,a.file_version_id,v.original_file_name,v.media_type,v.size_bytes,a.created_at_utc from barang.workflow_decision_attachments a join barang.file_versions v on v.company_id=a.company_id and v.id=a.file_version_id where a.company_id=@company and a.order_id=@order order by a.created_at_utc,a.id", ("company", Company), ("order", orderId)); await using DbDataReader r = await q.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) rows.Add(new DecisionAttachmentView(r.GetGuid(0), r.GetGuid(1), r.GetGuid(2), r.GetGuid(3), r.GetString(4), r.GetString(5), r.GetInt64(6), r.GetFieldValue<DateTimeOffset>(7))); return Result.Success<IReadOnlyList<object>>(rows); }
    public async Task<Result<WorkflowFileDownload>> DownloadDecisionAttachmentAsync(Guid id, CancellationToken ct) { await using DbConnection c = db.Database.GetDbConnection(); await c.OpenAsync(ct); await SetCompany(c, ct); await using DbCommand q = Cmd(c, "select file_id,file_version_id from barang.workflow_decision_attachments where company_id=@company and id=@id", ("company", Company), ("id", id)); await using DbDataReader r = await q.ExecuteReaderAsync(ct); if (!await r.ReadAsync(ct)) return Result.Failure<WorkflowFileDownload>(Error.NotFound("workflow.decision_attachment.not_found")); Guid fileId = r.GetGuid(0), versionId = r.GetGuid(1); Result<DownloadFile> f = await files.DownloadAsync(fileId, versionId, ct); return f.IsFailure ? Result.Failure<WorkflowFileDownload>(f.Error) : Result.Success(new WorkflowFileDownload(f.Value.FileName, f.Value.MediaType, f.Value.Length, f.Value.Content)); }
    public Task<Result<IReadOnlyList<object>>> ForwardTargetsAsync(Guid id, string? search, CancellationToken ct) => Task.FromResult(Result.Success<IReadOnlyList<object>>(Array.Empty<object>()));
